-- load_stock_holding_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.StockHolding_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedStockHoldingData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. GetStockHoldingUpdates takes no time window: it returns every current row.
--    Only one batch of data exists, so dev and holdout are split by [WWI Stock Item ID]:
--    even IDs are the dev batch (the default), odd IDs the holdout.
DECLARE @IdRemainder  int = 0;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Stock Holding');
DECLARE @NewCutoff  datetime2(7) = @LastLoad;

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.StockHolding_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [Quantity On Hand] int,
    [Bin Location] nvarchar(20),
    [Last Stocktake Quantity] int,
    [Last Cost Price] decimal(18,2),
    [Reorder Level] int,
    [Target Stock Level] int,
    [WWI Stock Item ID] int
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetStockHoldingUpdates;

INSERT INTO Integration.StockHolding_Staging ([Quantity On Hand], [Bin Location], [Last Stocktake Quantity], [Last Cost Price], [Reorder Level], [Target Stock Level], [WWI Stock Item ID])
SELECT [Quantity On Hand], [Bin Location], [Last Stocktake Quantity], [Last Cost Price], [Reorder Level], [Target Stock Level], [WWI Stock Item ID]
FROM #rows
WHERE [WWI Stock Item ID] % 2 = @IdRemainder;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedStockHoldingData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Stock Holding', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @NewCutoff AS window_to
FROM Integration.StockHolding_Staging;
